    return request<AccountResponse>("/auth/register", {
      method: "POST",
      body: JSON.stringify(credentials),
    });
  },

  login(credentials: Credentials): Promise<SessionResponse> {
    return request<SessionResponse>("/auth/login", {
      method: "POST",
      body: JSON.stringify(credentials),
    });
  },

  logout(): Promise<SessionResponse> {
    return request<SessionResponse>("/auth/logout", { method: "POST" });
  },

  confirmCheckout(payload: CheckoutRequest): Promise<CheckoutConfirmation> {
    return request<CheckoutConfirmation>("/checkout/confirm", {
      method: "POST",
      body: JSON.stringify(payload),
    });
  },

  // --- Stage 2: reviews with images and moderation ---------------------------

  /** List the approved reviews, rating summary, and own review for a product. */
  listProductReviews(productId: string): Promise<ProductReviews> {
    return request<ProductReviews>(
      `/products/${encodeURIComponent(productId)}/reviews`,
    );
  },

  /** Submit a review for a product (requires an active customer session). */
  submitReview(
    productId: string,
    submission: ReviewSubmission,
  ): Promise<Review> {
    return request<Review>(
      `/products/${encodeURIComponent(productId)}/reviews`,
      { method: "POST", body: JSON.stringify(submission) },
    );
  },

  /** Absolute URL for a stored review image, for direct use by an <img>. */
  reviewImageUrl(relativeImageUrl: string): string {
    return `${API_BASE_URL}${relativeImageUrl}`;
  },

  /** List the moderation queue of pending reviews (moderator session required). */
  listModerationQueue(): Promise<Review[]> {
    return request<Review[]>("/moderation/reviews");
  },

  /** Approve a pending review (moderator session required). */
  approveReview(reviewId: string): Promise<Review> {
    return request<Review>(
      `/moderation/reviews/${encodeURIComponent(reviewId)}/approve`,
      { method: "POST" },
    );
  },

  /** Reject a pending review (moderator session required). */
  rejectReview(reviewId: string): Promise<Review> {
    return request<Review>(
      `/moderation/reviews/${encodeURIComponent(reviewId)}/reject`,
      { method: "POST" },
    );
  },
};

export type ApiClient = typeof apiClient;

