  "products: $($p.Count)"
  $body = @{ identifier='moderator'; password='moderator123' } | ConvertTo-Json
  $s = New-Object Microsoft.PowerShell.Commands.WebRequestSession
  $login = Invoke-RestMethod -Uri http://127.0.0.1:18200/auth/login -Method Post -Body $body -ContentType 'application/json' -WebSession $s
  "login active=$($login.active) isModerator=$($login.isModerator) tokenExposed=$([bool]$login.token)"
  $q = Invoke-RestMethod -Uri http://127.0.0.1:18200/moderation/reviews -WebSession $s
  "moderation queue reachable as moderator (count=$($q.Count))"
} catch { "ERR: $_" }

